export const RADIOGRAPH_CELLS = 96 as const;

/** 96x96 attenuation bytes, base64. Decoded once on first use. */
const PACKED = "";

let decoded: Float32Array | null = null;

/** 0-1 attenuation per cell, row-major from the top-left. */
export function radiographField(): Float32Array {
  if (decoded) return decoded;
  const bin = atob(PACKED);
  const out = new Float32Array(bin.length);
  for (let i = 0; i < bin.length; i += 1) out[i] = bin.charCodeAt(i) / 255;
  decoded = out;
  return out;
}

